import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def acts(offset=0):
        cs = 0
        ds = 0
        for i in range(offset, n):
            if history[i][1] == 'C':
                cs += 1
            else:
                ds += 1
        return cs, ds

    my_c, my_d = 0, 0
    op_c, op_d = 0, 0
    for i in range(n):
        if history[i][0] == 'C':
            my_c += 1
        else:
            my_d += 1
        if history[i][1] == 'C':
            op_c += 1
        else:
            op_d += 1

    rounds_left = 100 - n
    if rounds_left <= 0:
        return 'D'

    # Detect stochastic/random-like behavior and defect when profitable.
    op_rate = op_c / float(n)
    my_rate = my_c / float(n)

    # Endgame exploitation: last few rounds, defect unless opponent is very cooperative
    if rounds_left <= 2:
        if op_rate > 0.95 and my_rate > 0.9 and n > 5:
            return 'C'
        return 'D'

    if rounds_left <= 8:
        if op_rate > 0.85 and op_d > 0:
            # hesitantly mix: defect more often near end
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        return 'D'

    # If opponent has shown random-ish, defect to exploit.
    if n >= 6:
        # Estimate opponent randomness via runs
        runs = 0
        for i in range(1, n):
            if history[i][1] != history[i - 1][1]:
                runs += 1
        expected = (op_c * op_d * 2.0) / n if n > 0 else 0
        # If changes near expected random level and rate ~0.5, exploit
        if 0.4 <= op_rate <= 0.6 and runs >= max(3, int(0.7 * expected)):
            return 'D'

    # Tit-for-tat with forgiveness and delayed punishment
    if n >= 1:
        last_my, last_op = history[n - 1]

        # If opponent just defected, consider retaliating
        if last_op == 'D':
            # count recent defections by opponent
            recent_d = 0
            look = min(n, 6)
            for i in range(n - look, n):
                if history[i][1] == 'D':
                    recent_d += 1
            recent_my_d = 0
            for i in range(n - look, n):
                if history[i][0] == 'D':
                    recent_my_d += 1

            # If opponent rarely defects, forgive once
            if op_rate > 0.75 and recent_d <= 1:
                return 'C'
            # If we've been defecting a lot already, maybe calm
            if recent_my_d >= 3 and recent_d == 1:
                return 'C'
            # otherwise punish
            return 'D'

        # Opponent cooperated last round
        # If we defected last round (exploiting), be cautious
        if last_my == 'D':
            # If opponent continues cooperating even after defection, exploit more
            if op_rate > 0.7 and op_c >= 3:
                return 'D'
            # Otherwise return to cooperation
            return 'C'

        # Both cooperated
        # If we're far ahead or opponent very cooperative, maybe probe
        if n >= 10 and op_rate > 0.9 and my_c > 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    return 'C'
